import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d as S,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"DNSSEC","description":"","frontmatter":{"title":"DNSSEC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dnssec.md","filePath":"cs/dnssec.md","lastUpdated":1789023840000}'),c={name:"cs/dnssec.md"};function D(h,a,E,_,N,C){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="dnssec" tabindex="-1">DNSSEC <a class="header-anchor" href="#dnssec" aria-label="Permalink to &quot;DNSSEC&quot;">​</a></h1><div class="epigraph"><p>权威用私钥签 RRSET，解析器沿 DS 链到根信任锚验证；防篡改与伪造，不加密查询。</p><footer>—— 据 RFC 4033 / 4034 / 4035 DNSSEC 整理</footer></div><p><a href="/cs/dns-cache-ttl">上一课</a> 的缓存可被毒化。主干 DNS 无认证。<a href="/cs/bgp-hijack-rpki">RPKI</a> 是路由侧同类问题。缺口是 <strong>DNSSEC</strong>：RRSIG、DNSKEY、DS、AD 位。本课不把 DoH 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UDP 查询易被伪造应答（缓存中毒）。DNSSEC：区签名，父区 DS 钉子区密钥，直到根。验证失败应 SERVFAIL，不能「软失败当没开」。NSEC/NSEC3 证明不存在。不提供机密：嗅探仍可见问了谁——下一课 DoH/DoT。与 RPKI 对照：都是 PKI 钉源，验证的对象是 DNS 节点 vs 前缀。</p><p>不要把 DNSSEC 写成让域名变安全浏览的全部。</p><p><span class="marginnote">RFC 4033–4035。密钥轮换与算法是运营。本课不写攻击步骤。</span></p><h3 id="完整性不是机密" tabindex="-1">完整性不是机密 <a class="header-anchor" href="#完整性不是机密" aria-label="Permalink to &quot;完整性不是机密&quot;">​</a></h3><p>链到根锚，失败应硬失败。不加密 QNAME。密钥轮换要时钟大致对。报文变大易截断。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：根锚 → TLD DS → 区 DNSKEY → RRSIG。对照 TLS：TLS 保护信道，DNSSEC 保护 DNS 数据。Cookie 无补。</p>',11)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANCH%5B%22%E6%A0%B9%E4%BF%A1%E4%BB%BB%E9%94%9A%22%5D%20--%3E%20DS%5B%22DS%20%E9%93%BE%22%5D%0A%20%20DS%20--%3E%20KEY%5B%22%E5%8C%BA%20DNSKEY%22%5D%0A%20%20KEY%20--%3E%20SIG%5B%22RRSIG%20%E8%A6%86%E7%9B%96%20RRSET%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>报文变大，易截断改 TCP，与 PMTUD 互动。TTL 内签名必须有效，时钟要大致对——后课 NTP。解析器 CPU 验签，放大攻击要限。CDN 多权威要共享或分签。</p><p>AD 位仅当解析器已验；应用若自己验更端到端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DANE 的全部。DoH/DoT 是下一课。后课默认：DNSSEC 完整性与真实性；非机密。</p><p>部署断裂（父 DS 不配）比不开更伤，表现为解析失败。</p><p>上一课留下的缺口在本课收口；「DNSSEC」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/doh-dot">DoH / DoT</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>签名链到根锚，防伪造应答。</li><li>不加密查询内容。</li><li>失败应硬失败，勿降级。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4033–4035。</li></ul>',10))])}const u=s(c,[["render",D]]);export{m as __pageData,u as default};
